// src/arttools/voronoi-madness/components/ControlPanel.js

import React from 'react';

const ControlPanel = ({
  handleRedistribute,
  handleClearPoints,
  handleDrawCurveToggle,
  handleClosedCurveToggle,
  isClosedCurveDrawing,
  handleUndo,
  handleRelaxPoints,
  drawing,
  inputNumPoints,
  handleNumPointsChange,
  inputRadius,
  handleRadiusChange,
  handleRadiusUpdate,
  inputSampledPoints,
  setInputSampledPoints,
  inputSampledPointsInRegion,
  setInputSampledPointsInRegion,
  cellBorderColor,
  setCellBorderColor,
  seedColor,
  setSeedColor,
  boundaryThickness,
  setBoundaryThickness,
}) => {
  return (
    <div>
      {/* Buttons */}
      <div className="row mb-3">
        <div className="col">
          <button className="btn btn-primary btn-round" onClick={handleRedistribute}>
            Randomize Points
          </button>
          <button className="btn btn-secondary btn-round ml-2" onClick={handleClearPoints}>
            Clear Points
          </button>
          <button className="btn btn-info btn-round ml-2" onClick={handleDrawCurveToggle}>
            {drawing ? 'Finish Curve' : 'Draw Curve'}
          </button>

          {/* New button for closed curve drawing */}
          <button className="btn btn-info btn-round ml-2" onClick={handleClosedCurveToggle}>
            {isClosedCurveDrawing ? 'Finish Closed Curve' : 'Draw Closed Curve'}
          </button>

          <button className="btn btn-warning btn-round ml-2" onClick={handleUndo}>
            Undo
          </button>
          <button className="btn btn-success btn-round ml-2" onClick={handleRelaxPoints}>
            Relax Points
          </button>
        </div>
      </div>

      {/* Controls */}
      <div className="row">
        {/* Number of Points */}
        <div className="col-md-4">
          <div className="form-group">
            <label htmlFor="numPoints">Number of Points:</label>
            <input
              type="number"
              id="numPoints"
              className="form-control"
              value={inputNumPoints}
              onChange={handleNumPointsChange}
              min="1"
            />
          </div>
        </div>
        {/* Dot Radius */}
        <div className="col-md-4">
          <div className="form-group">
            <label htmlFor="dotRadius">Dot Radius (0 to 20):</label>
            <input
              type="number"
              id="dotRadius"
              className="form-control"
              value={inputRadius}
              onChange={handleRadiusChange}
              min="0"
              max="20"
            />
          </div>
          <button
            className="btn btn-outline-secondary btn-sm mt-2"
            type="button"
            onClick={handleRadiusUpdate}
          >
            Update Radius
          </button>
        </div>
        {/* Number of Sampled Points Along Curves */}
        <div className="col-md-4">
          <div className="form-group">
            <label htmlFor="sampledPoints">Points Along Curves:</label>
            <input
              type="number"
              id="sampledPoints"
              className="form-control"
              value={inputSampledPoints}
              onChange={(e) => setInputSampledPoints(parseInt(e.target.value, 10) || 0)}
              min="1"
            />
          </div>
        </div>
      </div>

      {/* New Row for Points in Closed Region */}
      <div className="row">
        {/* Number of Points in Closed Region */}
        <div className="col-md-4">
          <div className="form-group">
            <label htmlFor="sampledPointsInRegion">Points in Closed Region:</label>
            <input
              type="number"
              id="sampledPointsInRegion"
              className="form-control"
              value={inputSampledPointsInRegion}
              onChange={(e) =>
                setInputSampledPointsInRegion(parseInt(e.target.value, 10) || 0)
              }
              min="1"
            />
          </div>
        </div>
      </div>

      {/* Color Pickers and Thickness Slider */}
      <div className="row mb-3 align-items-center">
        <div className="col-md-8 d-flex align-items-center">
          {/* Cell Boundary Color */}
          <div className="form-group mb-0 mr-3">
            <label htmlFor="cellBoundaryColor" className="mr-2">
              Cell Boundary:
            </label>
            <input
              type="color"
              id="cellBoundaryColor"
              className="color-picker"
              value={cellBorderColor}
              onChange={(e) => setCellBorderColor(e.target.value)}
            />
          </div>
          {/* Seed Color */}
          <div className="form-group mb-0">
            <label htmlFor="seedColor" className="mr-2">
              Seed Color:
            </label>
            <input
              type="color"
              id="seedColor"
              className="color-picker"
              value={seedColor}
              onChange={(e) => setSeedColor(e.target.value)}
            />
          </div>
        </div>
        {/* Boundary Thickness */}
        <div className="col-md-4">
          <div className="form-group mb-0">
            <label htmlFor="boundaryThickness" className="mr-2">
              Boundary Thickness:
            </label>
            <input
              type="range"
              id="boundaryThickness"
              className="form-control-range"
              min="1"
              max="10"
              value={boundaryThickness}
              onChange={(e) => setBoundaryThickness(e.target.value)}
            />
          </div>
        </div>
      </div>
    </div>
  );
};

export default ControlPanel;
