// src/arttools/voronoi-madness/components/DrawingCurvesLayer.js

import React from 'react';
import { Layer, Line, Circle } from 'react-konva';

const DrawingCurvesLayer = ({
  curves,
  currentCurve,
  closedCurves,
  currentClosedCurve,
  startPoint,
  isClosedCurveDrawing, // Added prop
}) => {
  return (
    <Layer>
      {/* Render existing open curves */}
      {curves.map((curve, i) => (
        <Line
          key={`curve-${i}`}
          points={curve.flatMap(({ x, y }) => [x, y])}
          stroke="black"
          strokeWidth={2}
          tension={0.5}
          lineCap="round"
        />
      ))}

      {/* Render the open curve currently being drawn */}
      {currentCurve.length > 0 && (
        <Line
          points={currentCurve.flatMap(({ x, y }) => [x, y])}
          stroke="black"
          strokeWidth={2}
          tension={0.5}
          lineCap="round"
        />
      )}

      {/* Render closed curves (if any) */}
      {closedCurves.map((curve, i) => (
        <Line
          key={`closed-curve-${i}`}
          points={curve.flatMap(({ x, y }) => [x, y])}
          stroke="blue"
          strokeWidth={2}
          tension={0.5}
          lineCap="round"
          closed
          fill="rgba(0, 0, 255, 0.2)" // Optional fill for visual feedback
        />
      ))}

      {/* Render the closed curve currently being drawn */}
      {isClosedCurveDrawing && currentClosedCurve.length > 0 && (
        <Line
          points={currentClosedCurve.flatMap(({ x, y }) => [x, y])}
          stroke="blue"
          strokeWidth={2}
          tension={0.5}
          lineCap="round"
        />
      )}

      {/* Render the starting point marker */}
      {startPoint && (
        <Circle
          x={startPoint.x}
          y={startPoint.y}
          radius={6} // Large dot
          fill="red"
        />
      )}
    </Layer>
  );
};

export default DrawingCurvesLayer;
