// src/arttools/voronoi-madness/VoronoiMadness.js

import React, { useState, useEffect, useRef } from 'react';
import {
  generateSeedPoints,
  constructVoronoiDiagram,
  performLloydsRelaxation,
} from './utils/generateSeeds';
import {
  calculateCurveLength,
  samplePointsAlongCurve,
  invertColor,
  isPointInPolygon,
  samplePointsInPolygon,
} from './utils/helpers';
// import '../../assets/css/paper-dashboard.css';
import './VoronoiMadness.css';

// Import components
import ControlPanel from './components/ControlPanel';
import CanvasStage from './components/CanvasStage';

const VoronoiMadness = () => {
  // State Variables
  const [numPoints, setNumPoints] = useState(50);
  const [inputNumPoints, setInputNumPoints] = useState(50);
  const [dotRadius, setDotRadius] = useState(3); // Default radius
  const [inputRadius, setInputRadius] = useState(3); // Text box input for radius (0 to 20)
  const [seedPoints, setSeedPoints] = useState([]);
  const [voronoiDiagram, setVoronoiDiagram] = useState(null);
  const [selectedPoints, setSelectedPoints] = useState([]);
  const [selectionRect, setSelectionRect] = useState(null);
  const [drawing, setDrawing] = useState(false); // Track if the user is in drawing mode
  const [curves, setCurves] = useState([]); // Store all drawn curves
  const [currentCurve, setCurrentCurve] = useState([]); // Track points on the current curve
  const stageRef = useRef(null);
  const isDrawing = useRef(false);
  const isSelecting = useRef(false);
  const selectionStart = useRef({ x: 0, y: 0 });
  const [inputSampledPoints, setInputSampledPoints] = useState(50); // Default to 50 points
  const [history, setHistory] = useState([]); // Track history for undo button
  const [cellBorderColor, setCellBorderColor] = useState('#008000'); // Default color for Voronoi cell boundaries (green)
  const [seedColor, setSeedColor] = useState('#FF0000'); // Default color for seeds (red)
  const [boundaryThickness, setBoundaryThickness] = useState(1); // Default thickness
  const [cellColors, setCellColors] = useState({});
  const [offSet, setOffSet] = useState({
    width: 40,
    height: 50,
  });
  const [stageSize, setStageSize] = useState({
    width: window.innerWidth - offSet.width,
    height: window.innerHeight - offSet.height,
  });

  // New State Variables for Closed Curve Drawing
  const [isClosedCurveDrawing, setIsClosedCurveDrawing] = useState(false); // Track if we are drawing a closed curve
  const [closedCurves, setClosedCurves] = useState([]); // Store all closed curves (may remain empty)
  const [currentClosedCurve, setCurrentClosedCurve] = useState([]); // Points in the current closed curve
  const [startPoint, setStartPoint] = useState(null); // Starting point of the closed curve

  // New State Variable for Number of Points in Closed Region
  const [inputSampledPointsInRegion, setInputSampledPointsInRegion] = useState(100); // Default to 100 points

  // Effect to generate initial seed points and Voronoi diagram
  useEffect(() => {
    // Generate initial seed points
    const initialSeedPoints = generateSeedPoints(
      numPoints,
      stageSize.width,
      stageSize.height
    );
    setSeedPoints(initialSeedPoints);

    // Construct Voronoi diagram
    const initialVoronoiDiagram = constructVoronoiDiagram(
      initialSeedPoints,
      stageSize.width,
      stageSize.height
    );
    setVoronoiDiagram(initialVoronoiDiagram);
  }, [numPoints, stageSize.width, stageSize.height]);

  // Effect to handle window resize
  useEffect(() => {
    const handleResize = () => {
      setStageSize({
        width: window.innerWidth - offSet.width,
        height: window.innerHeight - offSet.height,
      });
    };

    window.addEventListener('resize', handleResize);

    return () => {
      window.removeEventListener('resize', handleResize);
    };
  }, [offSet.width, offSet.height]);

  // Handler Functions

  // Redistribute (Randomize) Points
  const handleRedistribute = () => {
    updateHistory();
    setNumPoints(inputNumPoints);
    const newSeedPoints = generateSeedPoints(
      inputNumPoints,
      stageSize.width,
      stageSize.height
    );
    setSeedPoints(newSeedPoints);
    const newVoronoiDiagram = constructVoronoiDiagram(
      newSeedPoints,
      stageSize.width,
      stageSize.height
    );
    setVoronoiDiagram(newVoronoiDiagram);
  };

  // Clear Points
  const handleClearPoints = () => {
    updateHistory();
    setSeedPoints([]);
    setVoronoiDiagram(null);
  };

  // Relax Points
  const handleRelaxPoints = () => {
    updateHistory();
    const relaxedPoints = performLloydsRelaxation(seedPoints, voronoiDiagram);
    setSeedPoints(relaxedPoints);
    const newVoronoiDiagram = constructVoronoiDiagram(
      relaxedPoints,
      stageSize.width,
      stageSize.height
    );
    setVoronoiDiagram(newVoronoiDiagram);
  };

  // Update Dot Radius
  const handleRadiusUpdate = () => {
    const newRadius = Math.max(0, Math.min(inputRadius, 20)); // Ensure radius is within the range of 0 to 20
    setDotRadius(newRadius); // Apply the new radius
  };

  // Handle Number of Points Change
  const handleNumPointsChange = (e) => {
    const newInputNumPoints = parseInt(e.target.value, 10);
    if (!isNaN(newInputNumPoints) && newInputNumPoints > 0) {
      setInputNumPoints(newInputNumPoints);
    }
  };

  // Handle Radius Change
  const handleRadiusChange = (e) => {
    const newRadius = parseInt(e.target.value, 10);
    if (!isNaN(newRadius) && newRadius >= 0 && newRadius <= 20) {
      setInputRadius(newRadius);
    }
  };

  // Handle Draw Curve Toggle
  const handleDrawCurveToggle = () => {
    updateHistory();
    if (drawing) {
      // Finalize the current curve and sample points
      const totalLength = curves.reduce(
        (acc, curve) => acc + calculateCurveLength(curve),
        0
      );
      const pointsPerCurve = curves.map((curve) =>
        Math.round((calculateCurveLength(curve) / totalLength) * inputSampledPoints)
      );

      // Sample points along the curves and add them to the existing points
      const newSampledPoints = curves.flatMap((curve, i) =>
        samplePointsAlongCurve(curve, pointsPerCurve[i])
      );
      const updatedPoints = [...seedPoints, ...newSampledPoints]; // Add new points to existing points
      setSeedPoints(updatedPoints);

      // Recalculate Voronoi diagram with all points
      const newVoronoiDiagram = constructVoronoiDiagram(
        updatedPoints,
        stageSize.width,
        stageSize.height
      );
      setVoronoiDiagram(newVoronoiDiagram);

      // Reset curves for the next drawing
      setCurves([]);
      setDrawing(false);
      updateHistory(updatedPoints, newVoronoiDiagram);
    } else {
      // Start drawing without clearing existing points or diagram
      setDrawing(true);
    }
  };

  // Handle Closed Curve Toggle
  const handleClosedCurveToggle = () => {
    updateHistory();
    if (isClosedCurveDrawing) {
      // Finalize the current closed curve
      if (currentClosedCurve.length > 0 && startPoint) {
        // Ensure the curve is closed by connecting the last point to the start point
        const closedCurve = [...currentClosedCurve, startPoint];

        // Sample points within the closed curve
        const numPoints = inputSampledPointsInRegion;
        const sampledPoints = samplePointsInPolygon(closedCurve, numPoints);
        const updatedPoints = [...seedPoints, ...sampledPoints];
        setSeedPoints(updatedPoints);

        // Recalculate Voronoi diagram with all points
        const newVoronoiDiagram = constructVoronoiDiagram(
          updatedPoints,
          stageSize.width,
          stageSize.height
        );
        setVoronoiDiagram(newVoronoiDiagram);

        // Clear the current closed curve and reset states
        setCurrentClosedCurve([]);
        setIsClosedCurveDrawing(false);
        setStartPoint(null);

        updateHistory(updatedPoints, newVoronoiDiagram, curves, closedCurves);
      }
    } else {
      // Start drawing a closed curve
      setIsClosedCurveDrawing(true);
    }
  };

  // Handle Mouse Events
  const handleMouseDown = (e) => {
    const stage = e.target.getStage();
    const point = stage.getPointerPosition();

    if (isClosedCurveDrawing) {
      if (!startPoint) {
        // Start point of the closed curve
        setStartPoint(point);
        setCurrentClosedCurve([point]);
      } else {
        // Check if the user clicked near the starting point to close the curve
        const distance = Math.hypot(point.x - startPoint.x, point.y - startPoint.y);
        if (distance < 10) {
          // Close the curve
          handleClosedCurveToggle();
        } else {
          // Add point to the current closed curve
          setCurrentClosedCurve((prevPoints) => [...prevPoints, point]);
        }
      }
    } else if (drawing) {
      // Existing drawing logic
      isDrawing.current = true;
      setCurrentCurve([]);
    } else {
      const clickedPoint = e.target;

      if (clickedPoint.className === 'Circle') {
        const index = seedPoints.findIndex(
          (point) => point[0] === clickedPoint.x() && point[1] === clickedPoint.y()
        );

        if (index !== -1) {
          const newSelected = selectedPoints.includes(index)
            ? selectedPoints.filter((i) => i !== index) // Unselect if already selected
            : [...selectedPoints, index]; // Add to selection if not already selected

          setSelectedPoints(newSelected);
        }
      } else {
        // Selection box starts here
        isSelecting.current = true;
        const { x, y } = stage.getPointerPosition();
        selectionStart.current = { x, y };
        setSelectionRect({ x, y, width: 0, height: 0 });
      }
    }
  };

  const handleMouseMove = (e) => {
    const stage = e.target.getStage();
    const point = stage.getPointerPosition();

    if (isClosedCurveDrawing && currentClosedCurve.length > 0) {
      // Update current closed curve with the new point
      setCurrentClosedCurve((prevPoints) => [...prevPoints, point]);
    } else if (drawing && isDrawing.current) {
      // Existing drawing logic
      setCurrentCurve((prevPoints) => [...prevPoints, point]);
    } else if (isSelecting.current) {
      const { x, y } = e.target.getStage().getPointerPosition();
      const sx = selectionStart.current.x;
      const sy = selectionStart.current.y;
      setSelectionRect({
        x: Math.min(sx, x),
        y: Math.min(sy, y),
        width: Math.abs(x - sx),
        height: Math.abs(y - sy),
      });
    }
  };

  const handleMouseUp = () => {
    if (isClosedCurveDrawing) {
      // Nothing specific to do on mouse up for closed curves
    } else if (drawing && isDrawing.current) {
      isDrawing.current = false;
      setCurves((prevCurves) => [...prevCurves, currentCurve]); // Add the current curve to the list of curves
      setCurrentCurve([]); // Clear the current curve for new input
    } else if (isSelecting.current) {
      isSelecting.current = false;
      if (selectionRect) {
        const selected = seedPoints
          .map((point, i) => {
            const [px, py] = point;
            if (
              px > selectionRect.x &&
              px < selectionRect.x + selectionRect.width &&
              py > selectionRect.y &&
              py < selectionRect.y + selectionRect.height
            ) {
              return i;
            }
            return null;
          })
          .filter((i) => i !== null);

        setSelectedPoints(selected);
        setSelectionRect(null); // Clear selection rectangle
      }
    }
  };

  // Update History for Undo Functionality
  const updateHistory = (
    updatedPoints = seedPoints,
    updatedDiagram = voronoiDiagram,
    updatedCurves = curves,
    updatedClosedCurves = closedCurves
  ) => {
    const currentHistory = {
      seedPoints: updatedPoints,
      voronoiDiagram: updatedDiagram,
      drawing,
      curves: updatedCurves,
      currentCurve,
      closedCurves: updatedClosedCurves,
      currentClosedCurve,
      isClosedCurveDrawing,
      startPoint,
    };
    setHistory((prevHistory) => [...prevHistory, currentHistory]);
  };

  // Handle Undo
  const handleUndo = () => {
    if (history.length > 0) {
      const lastState = history[history.length - 1];

      setSeedPoints(lastState.seedPoints);
      setVoronoiDiagram(lastState.voronoiDiagram);
      setCurves(lastState.curves);
      setCurrentCurve(lastState.currentCurve);
      setDrawing(lastState.drawing);
      setClosedCurves(lastState.closedCurves);
      setCurrentClosedCurve(lastState.currentClosedCurve);
      setIsClosedCurveDrawing(lastState.isClosedCurveDrawing);
      setStartPoint(lastState.startPoint);
      setHistory(history.slice(0, -1));
    }
  };

  // Handle Drag Functionality
  const handleDragMove = (e, i) => {
    if (selectedPoints.length > 0) {
      const dx = e.target.x() - seedPoints[i][0];
      const dy = e.target.y() - seedPoints[i][1];
      const newPoints = [...seedPoints];
      selectedPoints.forEach((index) => {
        newPoints[index] = [newPoints[index][0] + dx, newPoints[index][1] + dy];
      });
      setSeedPoints(newPoints);
    }
  };

  const handleDragEnd = () => {
    const newVoronoiDiagram = constructVoronoiDiagram(
      seedPoints,
      stageSize.width,
      stageSize.height
    );
    setVoronoiDiagram(newVoronoiDiagram);
  };

  return (
    <div className="container-fluid mt-4">
      {/* Control Panel */}
      <ControlPanel
        handleRedistribute={handleRedistribute}
        handleClearPoints={handleClearPoints}
        handleDrawCurveToggle={handleDrawCurveToggle}
        handleClosedCurveToggle={handleClosedCurveToggle}
        isClosedCurveDrawing={isClosedCurveDrawing}
        handleUndo={handleUndo}
        handleRelaxPoints={handleRelaxPoints}
        drawing={drawing}
        inputNumPoints={inputNumPoints}
        handleNumPointsChange={handleNumPointsChange}
        inputRadius={inputRadius}
        handleRadiusChange={handleRadiusChange}
        handleRadiusUpdate={handleRadiusUpdate}
        inputSampledPoints={inputSampledPoints}
        setInputSampledPoints={setInputSampledPoints}
        inputSampledPointsInRegion={inputSampledPointsInRegion}
        setInputSampledPointsInRegion={setInputSampledPointsInRegion}
        cellBorderColor={cellBorderColor}
        setCellBorderColor={setCellBorderColor}
        seedColor={seedColor}
        setSeedColor={setSeedColor}
        boundaryThickness={boundaryThickness}
        setBoundaryThickness={setBoundaryThickness}
      />

      {/* Canvas Stage */}
      <CanvasStage
        stageRef={stageRef}
        stageSize={stageSize}
        handleMouseDown={handleMouseDown}
        handleMouseMove={handleMouseMove}
        handleMouseUp={handleMouseUp}
        voronoiDiagram={voronoiDiagram}
        cellBorderColor={cellBorderColor}
        boundaryThickness={boundaryThickness}
        seedPoints={seedPoints}
        selectedPoints={selectedPoints}
        dotRadius={dotRadius}
        seedColor={seedColor}
        invertColor={invertColor}
        handleDragMove={handleDragMove}
        handleDragEnd={handleDragEnd}
        selectionRect={selectionRect}
        currentCurve={currentCurve}
        curves={curves}
        // Props for closed curves
        isClosedCurveDrawing={isClosedCurveDrawing}
        closedCurves={closedCurves}
        currentClosedCurve={currentClosedCurve}
        startPoint={startPoint}
      />
    </div>
  );
};

export default VoronoiMadness;
