// src/arttools/voronoi-madness/components/VoronoiCellsLayer.js

import React from 'react';
import { Layer, Shape } from 'react-konva';

const VoronoiCellsLayer = ({ voronoiDiagram, cellBorderColor, boundaryThickness }) => {
  return (
    <Layer>
      {voronoiDiagram?.polygons().map((cell, i) => (
        <Shape
          key={i}
          sceneFunc={(context, shape) => {
            context.beginPath();
            cell.forEach(([x, y], index) => {
              if (index === 0) {
                context.moveTo(x, y);
              } else {
                context.lineTo(x, y);
              }
            });
            context.closePath();
            context.fillStrokeShape(shape);
          }}
          stroke={cellBorderColor}
          strokeWidth={boundaryThickness}
        />
      ))}
    </Layer>
  );
};

export default VoronoiCellsLayer;
