// src/arttools/voronoi-madness/utils/helpers.js

// Calculate the length of a curve
export const calculateCurveLength = (points) => {
    return points.reduce((acc, point, i) => {
      if (i === 0) return 0;
      const prev = points[i - 1];
      return acc + Math.hypot(point.x - prev.x, point.y - prev.y);
    }, 0);
  };
  
  // Sample points along a curve
  export const samplePointsAlongCurve = (points, numSamples) => {
    const sampled = [];
    const totalLength = calculateCurveLength(points);
    const stepLength = totalLength / numSamples;
  
    let accumulatedLength = 0;
    let currentSampleIndex = 0;
  
    for (let i = 1; i < points.length && sampled.length < numSamples; i++) {
      const prev = points[i - 1];
      const current = points[i];
      const segmentLength = Math.hypot(current.x - prev.x, current.y - prev.y);
      accumulatedLength += segmentLength;
  
      while (
        accumulatedLength > currentSampleIndex * stepLength &&
        sampled.length < numSamples
      ) {
        const t =
          (currentSampleIndex * stepLength - (accumulatedLength - segmentLength)) /
          segmentLength;
        const sampledX = prev.x + t * (current.x - prev.x);
        const sampledY = prev.y + t * (current.y - prev.y);
        sampled.push([sampledX, sampledY]);
        currentSampleIndex++;
      }
    }
    return sampled;
  };
  
  // Invert Color Utility Function
  export const invertColor = (hex) => {
    let color = hex.substring(1); // Strip #
    color = parseInt(color, 16); // Convert to integer
    color = 0xffffff ^ color; // Invert three bytes
    color = color.toString(16); // Convert back to hex
    color = ('000000' + color).slice(-6); // Pad with leading zeros
    return '#' + color; // Prepend #
  };
  
  // Point-in-Polygon function using ray casting algorithm
  export const isPointInPolygon = (point, polygon) => {
    const x = point.x,
      y = point.y;
    let isInside = false;
  
    for (let i = 0, j = polygon.length - 1; i < polygon.length; j = i++) {
      const xi = polygon[i].x,
        yi = polygon[i].y;
      const xj = polygon[j].x,
        yj = polygon[j].y;
  
      const intersect =
        yi > y !== yj > y && x < ((xj - xi) * (y - yi)) / (yj - yi) + xi;
      if (intersect) isInside = !isInside;
    }
  
    return isInside;
  };
  
  // Function to sample random points within a polygon
  export const samplePointsInPolygon = (polygon, numPoints) => {
    const points = [];
    // Compute bounding box
    const xs = polygon.map((p) => p.x);
    const ys = polygon.map((p) => p.y);
    const minX = Math.min(...xs);
    const maxX = Math.max(...xs);
    const minY = Math.min(...ys);
    const maxY = Math.max(...ys);
  
    while (points.length < numPoints) {
      const x = Math.random() * (maxX - minX) + minX;
      const y = Math.random() * (maxY - minY) + minY;
      const point = { x, y };
      if (isPointInPolygon(point, polygon)) {
        points.push([x, y]);
      }
    }
    return points;
  };
  