// src/arttools/voronoi-madness/components/SeedPointsLayer.js

import React from 'react';
import { Layer, Circle, Rect } from 'react-konva';

const SeedPointsLayer = ({
  seedPoints,
  selectedPoints,
  dotRadius,
  seedColor,
  invertColor,
  handleDragMove,
  handleDragEnd,
  selectionRect,
}) => {
  return (
    <Layer>
      {seedPoints.map(([x, y], i) => (
        <Circle
          key={i}
          x={x}
          y={y}
          radius={selectedPoints.includes(i) ? dotRadius * 2 : dotRadius}
          fill={selectedPoints.includes(i) ? invertColor(seedColor) : seedColor}
          draggable
          onDragMove={(e) => handleDragMove(e, i)}
          onDragEnd={handleDragEnd}
        />
      ))}

      {/* Draw selection rectangle */}
      {selectionRect && (
        <Rect
          x={selectionRect.x}
          y={selectionRect.y}
          width={selectionRect.width}
          height={selectionRect.height}
          stroke="blue"
          dash={[4, 4]}
        />
      )}
    </Layer>
  );
};

export default SeedPointsLayer;
