import * as d3 from 'd3-polygon';
import * as d3Voronoi from 'd3-voronoi';

// Step 1: Generate random seed points inside the blob
export function generateSeedPoints(numPoints, width, height) {
  const points = [];
  while (points.length < numPoints) {
    const x = Math.random() * width;
    const y = Math.random() * height;
    points.push([x, y]);  // Add the point to the array
  }
  return points;
}


// Step 2: Construct Voronoi diagram
export function constructVoronoiDiagram(seedPoints, width, height) {
  const voronoi = d3Voronoi.voronoi().extent([[0, 0], [width, height]]);
  return voronoi(seedPoints);  // Returns Voronoi diagram based on seed points
}

// Calculate the bounding box of the blob
function calculateBoundingBox(blobPath) {
  const xs = blobPath.map(p => p.x);
  const ys = blobPath.map(p => p.y);
  return [Math.min(...xs), Math.min(...ys), Math.max(...xs), Math.max(...ys)];
}

// Calculate the centroid of a Voronoi cell (polygon)
function calculateCentroid(polygon) {
  let x = 0, y = 0, area = 0;

  polygon.forEach(([x1, y1], i) => {
    const [x2, y2] = polygon[(i + 1) % polygon.length];
    const a = x1 * y2 - x2 * y1;
    area += a;
    x += (x1 + x2) * a;
    y += (y1 + y2) * a;
  });

  area *= 0.5;
  x /= (6 * area);
  y /= (6 * area);

  return [x, y];
}

// Perform one iteration of Lloyd's relaxation
export function performLloydsRelaxation(seedPoints, voronoiDiagram) {
  const newPoints = voronoiDiagram.polygons().map(polygon => {
    // Calculate the centroid of each Voronoi cell
    return calculateCentroid(polygon);
  });

  return newPoints;
}
