// src/arttools/voronoi-madness/components/CanvasStage.js

import React from 'react';
import { Stage } from 'react-konva';

// Import the components
import DrawingCurvesLayer from './DrawingCurvesLayer';
import VoronoiCellsLayer from './VoronoiCellsLayer';
import SeedPointsLayer from './SeedPointsLayer';

const CanvasStage = ({
  stageRef,
  stageSize,
  handleMouseDown,
  handleMouseMove,
  handleMouseUp,
  voronoiDiagram,
  cellBorderColor,
  boundaryThickness,
  seedPoints,
  selectedPoints,
  dotRadius,
  seedColor,
  invertColor,
  handleDragMove,
  handleDragEnd,
  selectionRect,
  currentCurve,
  curves,
  isClosedCurveDrawing,
  closedCurves,
  currentClosedCurve,
  startPoint,
}) => {
  return (
    <Stage
      ref={stageRef}
      width={stageSize.width}
      height={stageSize.height}
      onMouseDown={handleMouseDown}
      onMouseMove={handleMouseMove}
      onMouseUp={handleMouseUp}
    >
      {/* Drawing Curves Layer */}
      <DrawingCurvesLayer
        curves={curves}
        currentCurve={currentCurve}
        closedCurves={closedCurves}
        currentClosedCurve={currentClosedCurve}
        startPoint={startPoint}
        isClosedCurveDrawing={isClosedCurveDrawing} // Pass the prop
      />

      {/* Voronoi Cells Layer */}
      <VoronoiCellsLayer
        voronoiDiagram={voronoiDiagram}
        cellBorderColor={cellBorderColor}
        boundaryThickness={boundaryThickness}
      />

      {/* Seed Points Layer */}
      <SeedPointsLayer
        seedPoints={seedPoints}
        selectedPoints={selectedPoints}
        dotRadius={dotRadius}
        seedColor={seedColor}
        invertColor={invertColor}
        handleDragMove={handleDragMove}
        handleDragEnd={handleDragEnd}
        selectionRect={selectionRect}
      />
    </Stage>
  );
};

export default CanvasStage;
